### 双向链表

```java 纯粹的双向链表实现
public class DoublyLinkedList<T> {

    // 节点定义
    static class Node<T> {
        T value;
        Node<T> prev;
        Node<T> next;

        Node(T value) {
            this.value = value;
        }
    }

    private Node<T> head; // 虚拟头
    private Node<T> tail; // 虚拟尾
    private int size;

    public DoublyLinkedList() {
        head = new Node<>(null);
        tail = new Node<>(null);
        head.next = tail;
        tail.prev = head;
        size = 0;
    }

    // 在头部插入节点
    public void addFirst(T value) {
        Node<T> node = new Node<>(value);
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
        size++;
    }

    // 在尾部插入节点
    public void addLast(T value) {
        Node<T> node = new Node<>(value);
        node.prev = tail.prev;
        node.next = tail;
        tail.prev.next = node;
        tail.prev = node;
        size++;
    }

    // 删除指定节点
    public void remove(Node<T> node) {
        if (node == null || node == head || node == tail) return;
        node.prev.next = node.next;
        node.next.prev = node.prev;
        size--;
    }

    // 删除尾节点并返回
    public Node<T> removeLast() {
        if (tail.prev == head) return null; // 空链表
        Node<T> last = tail.prev;
        remove(last);
        return last;
    }

    // 获取链表长度
    public int getSize() {
        return size;
    }

    // 遍历打印（调试用）
    public void printList() {
        Node<T> curr = head.next;
        while (curr != tail) {
            System.out.print(curr.value + " ");
            curr = curr.next;
        }
        System.out.println();
    }
}

